import sys
from collections import deque

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = [list(line.rstrip()) for line in data[1:1 + n]]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    active = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] != 'P':
                continue
            # BFS starting from this piston
            dq = deque()
            dq.append((i, j))
            visited = [[False] * m for _ in range(n)]
            visited[i][j] = True
            found_r = False
            while dq:
                x, y = dq.popleft()
                if grid[x][y] == 'R':
                    found_r = True
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if not visited[nx][ny] and grid[nx][ny] != '.':
                            visited[nx][ny] = True
                            dq.append((nx, ny))
            if found_r:
                active += 1
    print(active)

if __name__ == "__main__":
    solve()

