from collections import deque

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = [list(data[i + 1].rstrip()) for i in range(n)]

    visited = [[False] * m for _ in range(n)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    active_pistons = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] != '.' and not visited[i][j]:
                # explore one connected component of non‑empty cells
                dq = deque([(i, j)])
                visited[i][j] = True
                pistons_in_comp = 0
                reds_in_comp = 0
                while dq:
                    x, y = dq.popleft()
                    if grid[x][y] == 'P':
                        pistons_in_comp += 1
                    elif grid[x][y] == 'R':
                        reds_in_comp += 1
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] != '.' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                dq.append((nx, ny))
                # if the component contains at least one redstone block, all pistons in it are active
                if reds_in_comp > 0:
                    active_pistons += pistons_in_comp

    print(active_pistons)

if __name__ == "__main__":
    solve()

