def can_reach(F, B, T, N):
    # tenta todos os possíveis números de saltos para frente (x)
    for x in range(N + 1):
        # depois de x saltos para frente estamos em x*F
        # precisamos chegar a T, então a diferença deve ser coberta por saltos para trás
        diff = x * F - T          # deve ser igual a y * B, com y >= 0
        if diff < 0:
            continue              # y seria negativo, não permitido
        if diff % B == 0:
            y = diff // B
            if y >= 0 and x + y <= N:
                return True
    return False

def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    F, B, T, N = map(int, data)
    print('YES' if can_reach(F, B, T, N) else 'NO')

if __name__ == "__main__":
    main()

