def can_reach(F, B, T, N):
    from collections import deque
    max_step = max(F, B)
    low = -N * max_step
    high = N * max_step
    visited = set()
    q = deque()
    q.append((0, 0))
    visited.add(0)
    while q:
        year, steps = q.popleft()
        if year == T:
            return True
        if steps == N:
            continue
        for nxt in (year + F, year - B):
            if low <= nxt <= high and nxt not in visited:
                visited.add(nxt)
                q.append((nxt, steps + 1))
    return False

def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    F, B, T, N = map(int, data)
    print('YES' if can_reach(F, B, T, N) else 'NO')

if __name__ == "__main__":
    main()

