def main():
    try:
        line1 = input().strip()
    except EOFError:
        return
    if not line1:
        print(0)
        return
    coeffs = list(map(float, line1.split()))
    try:
        line2 = input().strip()
    except EOFError:
        line2 = ''
    x = float(line2) if line2 else 0.0
    result = 0.0
    deg = len(coeffs) - 1
    for c in coeffs:
        result += c * (x ** deg)
        deg -= 1
    if result.is_integer():
        print(int(result))
    else:
        print(result)

if __name__ == "__main__":
    main()

